export function StatSequence(props: StatSequenceProps) {
  const {
    stats = DEFAULT_STATS,
    name = "remocn",
    eyebrow = "in numbers",
    logo,
    accent = "#3B5BFD",
    ink,
    background,
    fontFamily = sans,
    grain = true,
    scale = 1,
    delay = 0,
    speed = 1,
    theme = "dark",
    timing,
  } = props;
  const glide = useGlide();
  const frame = Math.max(0, useSceneFrame() - delay);
  const { width, height, durationInFrames } = useSceneConfig();
  const t = frame * speed;
  const tl = useTimeline(
    statSequenceTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const u = Math.min(width / 1280, height / 720);
  const c = THEMES[theme];
  const fg = ink ?? c.fg;
  const n = Math.max(1, stats.length);

  const intro = tl.get("intro");
  const statEls = Array.from({ length: n }, (_, i) => tl.get(`stat:${i}`));
  const inAt = (i: number) => statEls[i].start;
  // A stat leaves as the next one cuts in.
  const exitOf = (i: number) =>
    i === n - 1 ? 1e9 : inAt(i + 1) + statEls[i + 1].beat("cutAt");
  const summary = tl.get("summary");
  const M = summary.start; // the hero stat starts moving into the summary row

  const F = 196 * u; // monumental size
  const L = width * 0.08; // left rule of the frame
  const pad = 30 * u;
  const colW = (width - 2 * L) / n;
  const S = Math.min(0.42, (colW - pad * 1.6) / (F * 3.4)); // summary scale
  const bigTop = height / 2 - F * 0.6;
  const rowTop = height / 2 - (F * S * 1.12 + 70 * u) / 2;

  const mp = interpolate(t, [M, summary.end], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });

  // slow camera drift over the whole shot
  const drift = interpolate(t, [0, M + summary.beat("drift")], [0, 1], CLAMP);

  // accent bar: the cut marker. Grows from below on the first stat, swipes
  // up-and-out / up-and-in on every cut, retires as the row assembles.
  const barTop = bigTop + 0.18 * F;
  const barH = 0.72 * F;
  const first = statEls[0];
  let barScale = interpolate(
    t,
    [inAt(0) + first.beat("barAt"), inAt(0) + first.beat("barTo")],
    [0, 1],
    {
      ...CLAMP,
      easing: EASE_OUT,
    },
  );
  let barOrigin = "bottom";
  for (let i = 1; i < n; i++) {
    const cut = inAt(i);
    const outAt = cut + statEls[i].beat("barOutAt");
    const backAt = cut + statEls[i].beat("barInAt");
    const backTo = cut + statEls[i].beat("barTo");
    if (t >= outAt && t < backAt) {
      barScale = interpolate(t, [outAt, backAt], [1, 0], {
        ...CLAMP,
        easing: EASE_IN,
      });
      barOrigin = "top";
    } else if (t >= backAt && t < backTo) {
      barScale = interpolate(t, [backAt, backTo], [0, 1], {
        ...CLAMP,
        easing: EASE_OUT,
      });
      barOrigin = "bottom";
    }
  }
  const retireAt = M + summary.beat("barAt");
  if (t >= retireAt) {
    barScale = interpolate(t, [retireAt, M + summary.beat("barTo")], [1, 0], {
      ...CLAMP,
      easing: EASE_IN,
    });
    barOrigin = "top";
  }

  // index ticker, bottom left
  const idxSize = 15 * u;

  return (
    <AbsoluteFill
      style={{ background: background ?? c.bg, overflow: "hidden" }}
    >
      {/* mesh ground: three soft blobs that drift a few % over the shot */}
      {background === undefined ? (
        <AbsoluteFill
          style={{
            background: c.mesh.join(", "),
            transform: `translate(${drift * 3}%, ${-drift * 2}%) scale(${1.04 + drift * 0.04})`,
          }}
        />
      ) : null}

      <ScaleLayer scale={scale}>
        <AbsoluteFill
          style={{
            // Chrome parks a glyph raster on a whole pixel while its matrix is
            // axis-aligned, so text under the slow drift clicks along. The
            // drift outlasts the hero's move into the row, so this mark covers
            // every stat while anything on screen travels.
            transform: `scale(${1 + drift * 0.025}) translateX(${-drift * 6 * u}px)${glide(drift > 0 && drift < 1)}`,
            transformOrigin: "40% 50%",
          }}
        >
          {/* corner lockup */}
          <div
            style={{
              position: "absolute",
              left: L,
              top: 52 * u,
              display: "flex",
              alignItems: "center",
              gap: 10 * u,
              fontFamily,
              fontSize: 17 * u,
              lineHeight: 1,
              opacity: interpolate(
                t,
                [intro.start, intro.start + intro.beat("fade")],
                [0, 1],
                CLAMP,
              ),
              transform: `translateY(${interpolate(t, [intro.start, intro.end], [8, 0], { ...CLAMP, easing: EASE_OUT }) * u}px)`,
            }}
          >
            {logo ??
              (name.trim().toLowerCase() === "remocn" ? (
                <RemocnLogo fontSize={21 * u} color={fg} />
              ) : (
                <span
                  style={{
                    color: fg,
                    fontWeight: 500,
                    fontSize: 19 * u,
                    letterSpacing: "-0.02em",
                  }}
                >
                  {name}
                </span>
              ))}
            <span
              style={{
                width: Math.max(1, u),
                height: 16 * u,
                background: c.hair,
                margin: `0 ${2 * u}px`,
              }}
            />
            <span style={{ color: c.muted, fontWeight: 400 }}>{eyebrow}</span>
          </div>

          {/* the accent cut bar */}
          <div
            style={{
              position: "absolute",
              left: L,
              top: barTop,
              width: 5 * u,
              height: barH,
              borderRadius: 3 * u,
              background: c.bar,
              transform: `scaleY(${barScale})`,
              transformOrigin: barOrigin,
            }}
          />

          {/* one monumental stat at a time */}
          {stats.map((stat, i) => {
            const isLast = i === n - 1;
            const el = statEls[i];
            const enter = inAt(i);
            const exit = exitOf(i);
            if (t < enter - 1 || t > exit + 14) return null;
            const tx = isLast ? (n - 1) * colW * mp : 0;
            const ty = isLast ? (rowTop - bigTop) * mp : 0;
            const sc = isLast ? 1 + (S - 1) * mp : 1;
            return (
              <div
                key={i}
                style={{
                  position: "absolute",
                  left: L + pad,
                  top: bigTop,
                  display: "flex",
                  alignItems: "flex-end",
                  gap: 34 * u,
                  transformOrigin: "0 0",
                  transform: `translate(${tx}px, ${ty}px) scale(${sc})`,
                }}
              >
                <Figure
                  stat={stat}
                  t={t}
                  enter={enter}
                  exit={exit}
                  size={F}
                  u={u}
                  c={c}
                  accent={accent}
                  fg={fg}
                  solid={ink !== undefined}
                  font={fontFamily}
                  stagger={el.beat("stagger")}
                />
                <div style={{ paddingBottom: 0.2 * F }}>
                  <Caption
                    stat={stat}
                    t={t}
                    enter={enter + el.beat("captionAt")}
                    exit={isLast ? M + summary.beat("captionOut") : exit}
                    labelSize={34 * u}
                    c={c}
                    fg={fg}
                    font={fontFamily}
                  />
                </div>
              </div>
            );
          })}

          {/* summary row: column rules, the other figures, labels below */}
          {stats.map((stat, i) => {
            const colLeft = L + i * colW;
            const ruleP = interpolate(
              t,
              [
                M + summary.beat("ruleAt") + i * summary.beat("ruleGap"),
                M + summary.beat("ruleTo") + i * summary.beat("ruleGap"),
              ],
              [0, 1],
              { ...CLAMP, easing: EASE_OUT },
            );
            const isLast = i === n - 1;
            const figEnter =
              M + summary.beat("figAt") + i * summary.beat("figGap");
            return (
              <div key={`row-${i}`}>
                <div
                  style={{
                    position: "absolute",
                    left: colLeft,
                    top: rowTop - 6 * u,
                    width: Math.max(1, u),
                    height: F * S + 120 * u,
                    background: c.hair,
                    transform: `scaleY(${ruleP})`,
                    transformOrigin: "top",
                  }}
                />
                {!isLast && t >= figEnter - 1 ? (
                  <div
                    style={{
                      position: "absolute",
                      left: colLeft + pad,
                      top: rowTop,
                      transformOrigin: "0 0",
                      transform: `scale(${S})`,
                    }}
                  >
                    <Figure
                      stat={stat}
                      t={t}
                      enter={figEnter}
                      exit={1e9}
                      size={F}
                      u={u}
                      c={c}
                      accent={accent}
                      fg={fg}
                      solid={ink !== undefined}
                      font={fontFamily}
                      stagger={statEls[i].beat("stagger")}
                    />
                  </div>
                ) : null}
                <div
                  style={{
                    position: "absolute",
                    left: colLeft + pad,
                    top: rowTop + F * S * 1.12 + 14 * u,
                  }}
                >
                  <Caption
                    stat={stat}
                    t={t}
                    enter={
                      M + summary.beat("labelAt") + i * summary.beat("figGap")
                    }
                    exit={1e9}
                    labelSize={22 * u}
                    detailSize={15 * u}
                    c={c}
                    fg={fg}
                    font={fontFamily}
                  />
                </div>
              </div>
            );
          })}

          {/* index ticker */}
          <div
            style={{
              position: "absolute",
              left: L,
              bottom: 48 * u,
              display: "flex",
              alignItems: "center",
              gap: 8 * u,
              fontFamily: mono,
              fontWeight: 400,
              fontSize: idxSize,
              lineHeight: 1,
              fontVariantNumeric: "tabular-nums",
              color: c.muted,
              opacity:
                interpolate(
                  t,
                  [
                    intro.start + intro.beat("indexAt"),
                    intro.start + intro.beat("indexAt") + intro.beat("index"),
                  ],
                  [0, 1],
                  CLAMP,
                ) *
                interpolate(t, [M, M + summary.beat("index")], [1, 0], CLAMP),
            }}
          >
            <span
              style={{
                position: "relative",
                display: "inline-block",
                overflow: "hidden",
                height: idxSize * 1.15,
                width: idxSize * 1.4,
                color: fg,
              }}
            >
              {stats.map((_, i) => (
                <span
                  key={i}
                  style={{ position: "absolute", left: 0, top: idxSize * 0.06 }}
                >
                  <SlotText
                    text={String(i + 1).padStart(2, "0")}
                    t={t}
                    enter={
                      i === 0 ? intro.start + intro.beat("indexAt") : inAt(i)
                    }
                    exit={exitOf(i)}
                    stagger={1}
                    u={u * 0.3}
                  />
                </span>
              ))}
            </span>
            <span
              style={{
                width: 18 * u,
                height: Math.max(1, u),
                background: c.hair,
              }}
            />
            <span>{String(n).padStart(2, "0")}</span>
          </div>
        </AbsoluteFill>
      </ScaleLayer>

      {grain ? <Grain opacity={c.grain} /> : null}
    </AbsoluteFill>
  );
}
